// Parsed JKSSB score sheets. Each row: [rank, roll, "NAME + PARENTAGE as printed", marks].
// Generated by research/jkssb/tools/parse_result.py from the official result PDF.

import jeCivil2025 from "./je-civil-2025.json";

export type ResultRow = [number, string, string, number];

export interface ResultSheet {
  slug: string;
  title: string;
  examDate: string;
  declared: string;
  outOf: number;
  pdf: string;
  /** Exam page with past cut-offs for context */
  examSlug?: string;
  rows: ResultRow[];
}

export const resultSheets: ResultSheet[] = [
  {
    slug: "jkssb-je-civil-2025",
    title: "JKSSB Junior Engineer (Civil) 2025",
    examDate: "2 Nov 2025",
    declared: "24 Nov 2025",
    outOf: 120,
    pdf: "https://jkssb.nic.in/Pdf/RESULT_CIVIL%20_24112025.pdf",
    examSlug: "junior-engineer-civil",
    rows: jeCivil2025 as ResultRow[],
  },
];

export function getResultSheet(slug: string) {
  return resultSheets.find((s) => s.slug === slug) ?? null;
}
